// v5 part "stage" (owner: stage agent): the console bank on the front-left diagonal, the turnaround reveal,
// the camera presets and the 4-spot light rig. Data: /assets/models/builder/hangar/v5/stage.json
// (generated by src/builder/tools/blender/hangar/v5-stage-check.mjs --write; island GLB by v5_stage.py).
// Contract: createStage(ctx) returns {update(dt), redraw(), cancelReveal(), objects[]} (+ sit, stand, setDistance).
import {createConsoles} from './role1.hangar.consoles-v4.js';
import {createBank,titles} from './role1.hangar.consoles-v5.js';

const ML_TOP=7,EYE=1.7;
const smooth=t=>{t=Math.min(1,Math.max(0,t));return t*t*(3-2*t);};
// Frame the whole ship (launcher top Y 7 to the tip) from an eye on the ground: pitch at the angular midpoint,
// vertical FOV = angular span + ~10 % margin each side, kept within 52..75 degrees (same rule as stage.json).
export function frameShip(eye,top){
  const d=Math.hypot(eye[0],eye[2]),base=Math.atan2(ML_TOP-eye[1],d),tip=Math.atan2(ML_TOP+top-eye[1],d),pitch=(base+tip)/2;
  return {target:[0,eye[1]+d*Math.tan(pitch),0],fov:Math.min(75,Math.max(52,(tip-base)*180/Math.PI*1.2))};
}

export function createStage(ctx){
  const {THREE,scene,assets,camera,controls,params,actions,look,rig,gui,cameraGui,fragment:data,ship}=ctx;
  // Without stage data (or the island module) fall back to Codex's frontal v4 bank.
  if(!data?.banks)return createConsoles(ctx);
  const V=THREE.Vector3;
  params.bankDistance=data.bankDistance??18;
  let bank=data.banks[params.bankDistance];
  const consoleBank=createBank({...ctx,consoles:bank.consoles});
  const islandSource=assets.get(bank.island.module),island=islandSource?islandSource.clone(true):new THREE.Group();
  island.name='bank_island_v5';scene.add(island);
  const objects=[...(consoleBank?.objects??[]),island];
  const top=()=>ship()?.top??params.height;
  const deg=THREE.MathUtils.degToRad;
  const u=new V(-Math.SQRT1_2,0,-Math.SQRT1_2);// forward along the diagonal, towards the front-left corner
  const local=(st,[x,y,z])=>{const a=deg(st.rotation[1]),c=Math.cos(a),s=Math.sin(a);return [st.position[0]+x*c+z*s,y,st.position[2]-x*s+z*c];};

  // In-hall views need the real front wall (cutaway hides the z=-22 panels and the door); the outside overview may cut it away.
  const cutawayCtl=()=>gui.controllersRecursive?.().find(c=>c.property==='cutaway');
  function go(pos,target,fov,cutaway=false){
    const changed=params.cutaway!==cutaway;params.cutaway=cutaway;cutawayCtl()?.updateDisplay();
    look(pos,target,fov);if(changed&&!params.lod)ctx.rebuild();
  }
  let lastView=null;const remember=(key,fn)=>(...a)=>{lastView=key;return fn(...a);};

  // ---- sit, stand up and turn around ----
  let active=null,reveal=null;
  function sit(id){
    const st=bank.consoles.find(s=>s.id===id)??bank.consoles[3];active=st;reveal=null;
    go(st.seatedEye,st.seatedTarget,68,false);controls.enabled=false;
    if(st.id==='station_builder')ctx.builderFolder?.open();
    consoleBank.showEditor(st.id==='station_builder',stand);
  }
  function stand(){
    if(!active)return;
    const st=bank.consoles.find(s=>s.id===active.id)??active;
    const to=new V(...st.turnaroundView.position),f=frameShip(st.turnaroundView.position,top()),target=new V(...f.target);
    const from=camera.position.clone(),e0=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ');
    // Camera yaw (YXZ) for a horizontal direction (x,z) is atan2(-x,-z); pitch is the elevation angle.
    const toYaw=Math.atan2(-(target.x-to.x),-(target.z-to.z)),toPitch=Math.atan2(target.y-to.y,Math.hypot(target.x-to.x,target.z-to.z));
    let dYaw=toYaw-e0.y;while(dYaw>Math.PI)dYaw-=2*Math.PI;while(dYaw<-Math.PI)dYaw+=2*Math.PI;
    // Near 180 degrees, turn over the shoulder that faces the bank's centre line (the diagonal), so the turn sweeps across the bank.
    if(Math.abs(dYaw)>2.6){const fwd=new V(-Math.sin(e0.y),0,-Math.cos(e0.y)),e=from.clone().sub(new V(...bank.centre)).setY(0),v=e.clone().addScaledVector(u,-e.dot(u)).negate();const want=fwd.x*v.z-fwd.z*v.x<0?1:-1;if(Math.sign(dYaw)!==want)dYaw-=Math.sign(dYaw)*2*Math.PI;}
    reveal={t:0,from,to,yaw0:e0.y,dYaw,pitch0:e0.x,pitch1:toPitch,fov0:camera.fov,fov1:f.fov,target};
    controls.enabled=false;consoleBank.showEditor(false);lastView='turnaround';
  }
  function cancelReveal(){reveal=null;consoleBank?.showEditor(false);}

  // ---- light rig: 4 spots, no shadows, calm v4 levels ----
  // 0: ceiling wash over the open quarter, slot faces and the bank. 1: ceiling wash over the far (back-right) decks.
  // 2: key on the lower ship from the front, near the fr slot face. 3: fill on the upper ship from the left, near the bl slot face.
  const rigPower=[2600,3200,520,600];
  rig.forEach((l,i)=>{l.userData.power=rigPower[i];if(params.gameLook)l.intensity=rigPower[i];l.castShadow=false;});
  function aimRig(){
    const h=top();
    rig[0].position.set(-6,73,-6);rig[0].target.position.set(-4,0,-4);rig[0].angle=.3;
    rig[1].position.set(12,73,12);rig[1].target.position.set(5,0,5);
    rig[2].position.set(-3,9+h*.3,-17);rig[2].target.position.set(0,ML_TOP+h*.32,0);
    rig[3].position.set(-17,Math.min(70,14+h*.75),-4);rig[3].target.position.set(0,ML_TOP+h*.72,0);
    for(const l of rig)l.target.updateMatrixWorld();
  }

  // ---- bank distance ----
  function setDistance(d){
    d=Number(d);if(!data.banks[d])return;params.bankDistance=d;bank=data.banks[d];
    consoleBank.place(bank.consoles);
    island.position.fromArray(bank.island.position);island.rotation.set(0,deg(bank.island.rotation[1]),0);island.updateMatrixWorld(true);
    if(active)active=bank.consoles.find(s=>s.id===active.id);
    if(lastView&&lastView!=='turnaround'&&views[lastView])views[lastView]();
  }

  // ---- camera presets ----
  const views={
    slotView:()=>{const f=frameShip(bank.eye,top());go(bank.eye,f.target,f.fov,false);},
    wrapOverview:()=>{const h=top();go([-15,ML_TOP+h*.9+10,-31],[0,ML_TOP+h*.45,0],55,true);},
    consoleWide:()=>{const c=new V(...bank.centre),back=Math.min(3,params.bankDistance-12.3);go(c.clone().addScaledVector(u,-back).setY(3.1).toArray(),c.clone().addScaledVector(u,2.6).setY(.9).toArray(),70,false);},
    seatedView:()=>sit(active?.id??'station_testfire'),
  };
  for(const st of bank.consoles)views['close_'+st.id]=()=>{const s=bank.consoles.find(x=>x.id===st.id);go(local(s,[.5,1.8,2.5]),local(s,[0,1.45,-.1]),58,false);};
  for(const [key,fn] of Object.entries(views))actions[key]=remember(key,fn);
  // Labels for the new buttons; slot view, wrap overview, console bank and the close-ups already have buttons in v5.js.
  cameraGui.add(actions,'seatedView').name('Seated view');
  const folder=gui.addFolder('Engineering console bank');
  folder.add(params,'bankDistance',data.bankDistances??[18,22]).name('Bank distance (m)').onChange(setDistance);
  bank.consoles.forEach((st,i)=>{actions['sit_'+st.id]=()=>{lastView=null;sit(st.id);};folder.add(actions,'sit_'+st.id).name('Sit: '+titles[i]);});
  actions.turnaround=stand;folder.add(actions,'turnaround').name('Stand up and turn around');
  cameraGui.add(actions,'turnaround').name('Stand up and turn around');

  setDistance(params.bankDistance);aimRig();
  return {
    objects,sit,stand,setDistance,frameShip,cancelReveal,
    get bank(){return bank;},get active(){return active?.id;},get revealing(){return Boolean(reveal);},
    redraw(){consoleBank?.redraw();aimRig();},
    update(dt){
      aimRig();
      if(!reveal)return;
      reveal.t=Math.min(1,reveal.t+dt/1.5);const t=reveal.t;
      // 0-0.45: stand up; 0.15-1: step back and turn; pitch rises in the second half; FOV widens with it.
      const up=smooth(t/.45),turn=smooth((t-.15)/.85),tilt=smooth((t-.4)/.6);
      camera.position.set(THREE.MathUtils.lerp(reveal.from.x,reveal.to.x,turn),THREE.MathUtils.lerp(reveal.from.y,reveal.to.y,up),THREE.MathUtils.lerp(reveal.from.z,reveal.to.z,turn));
      camera.quaternion.setFromEuler(new THREE.Euler(THREE.MathUtils.lerp(reveal.pitch0,reveal.pitch1,tilt),reveal.yaw0+reveal.dYaw*turn,0,'YXZ'));
      camera.fov=THREE.MathUtils.lerp(reveal.fov0,reveal.fov1,tilt);camera.updateProjectionMatrix();
      if(t===1){controls.target.copy(reveal.target);controls.enabled=true;controls.update();reveal=null;}
    },
  };
}
